import json,subprocess,sys,traceback
from pathlib import Path
from experiments.openexempt_online import ROOT,read,sha,now,preserve
from legal_skill_guard.experiment.storage import RunStore
group="legal_openexempt_v6_EV_phase_contract_TRAIN12_20261031_run01"
qroot=ROOT/"artifacts/launches/openexempt_v6_EV_phase_only_screen_confirm_20261031_run01"
intent=read(qroot/"intent.json")
for name,digest in intent["bindings"].items():
    if sha(ROOT/name)!=digest: raise ValueError("Operational handoff changed: "+name)
def execute(stage,freeze_stage):
    config="configs/openexempt_v6_EV_phase_contract_TRAIN12_"+stage+"_20261031_run01.json"
    if freeze_stage:
        subprocess.run([sys.executable,"-u","-m","experiments.openexempt_ev_representation","freeze",config],cwd=ROOT,check=True)
    subprocess.run([sys.executable,"-u","-m","experiments.openexempt_ev_representation","run",config],cwd=ROOT,check=True)
    run=ROOT/"runs"/(group+"_"+stage)
    if (run/"failure.json").exists() or len(read(run/"terminal_preservation.json")["paths"])!=2:
        raise ValueError("Stage did not complete and preserve cleanly: "+stage)
    return read(run/"completion.json")
try:
    result=execute("screen",False)
    states={"screen":result["status"]}
    if result["status"]=="completed_screen_qualified":
        result=execute("confirm",True)
        states["confirm"]=result["status"]
    elif result["status"]!="closed_no_qualified_representation":
        raise ValueError("Unexpected original screen state")
    next_step=("declare_new_empty_formal_recipe_and_genuinely_matched_controls_before_training"
               if result["status"]=="completed_eligible_for_new_formal_recipe"
               else "close_this_diagnostic_direction_then_adopt_existing_v6_and_start_prepared_required_teacher_execution_withheld_control")
    if result["status"] not in ("completed_eligible_for_new_formal_recipe","closed_no_qualified_representation","closed_full128_not_qualified"):
        raise ValueError("Unexpected diagnostic final state")
    value={"at":now(),"status":"completed_bounded_screen_and_conditional_confirmation","stage_states":states,"next_scientific_step":next_step,
           "no_automatic_quality_retry_or_formal_recipe_change":True,"new_TEST_semantics_unopened":True}
    RunStore.immutable_json(qroot/"completion.json",value)
    print(json.dumps(value),flush=True)
except BaseException as exc:
    RunStore.immutable_json(qroot/"failure.json",{"at":now(),"error":repr(exc),"traceback":traceback.format_exc(),"no_auto_restart":True})
    raise
finally:
    names=[str(p.relative_to(ROOT)) for p in qroot.glob("*.json") if p.name!="terminal_preservation.json"]
    RunStore.immutable_json(qroot/"terminal_preservation.json",preserve(group,"screen-confirm-queue-terminal",names))
